alter table public.products add column if not exists short_description_en text, add column if not exists description_en text;
comment on column public.products.short_description_en is 'Optional English product summary. Spanish is the storefront fallback.';
comment on column public.products.description_en is 'Optional full English product description, shown by Read more.';
update public.products set short_description_en=coalesce(nullif(short_description_en,''),nullif(specifications->>'short_description_en',''),nullif(specifications->>'english_short_description',''),nullif(specifications->>'short description english','')), description_en=coalesce(nullif(description_en,''),nullif(specifications->>'description_en',''),nullif(specifications->>'english_description',''),nullif(specifications->>'description english','')) where (short_description_en is null or description_en is null) and specifications ?| array['short_description_en','english_short_description','short description english','description_en','english_description','description english'];
insert into public.storefront_texts(key,source_text,es,en) values ('product.shippingExcluded','Envío no incluido','Envío no incluido','Shipping not included') on conflict(key) do update set source_text=excluded.source_text,es=excluded.es,en=excluded.en,updated_at=now();
